import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameter: an arbitrary caller address that the fuzzer will try.
    function testFuzz_property(address caller) public {
        // keep wide: disallow the zero address since it's not a meaningful actor for this property
        vm.assume(caller != address(0));

        // The reference contract enforces only admin (deployer) may call setOwner.
        // We exercise setOwner from an arbitrary caller (not the admin) and then assert that
        // owner did NOT change to that caller. The correct contract always prevents non-admins
        // from changing owner, so owner() != caller for any non-admin caller; the mutant allows
        // some non-admin caller to change owner, so the assertion will fail for those inputs.

        // Ensure caller is not the admin (admin is address(this) at deployment time? Actually admin was set to msg.sender at C construction, which in setUp() is this test contract. So admin == address(this).)
        vm.assume(caller != address(this));

        // Call setOwner as the fuzzed caller
        vm.prank(caller);
        bool ok;
        try c.setOwner(caller) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }

        // Exactly one assertion reading c's public getter: owner() must NOT equal the fuzzed non-admin caller.
        // In the correct contract, non-admins cannot set owner, so owner() remains the deployer (set in constructor), not `caller`.
        assertTrue(c.owner() != caller);
    }
}

