contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: adminCaller is the address that will act as admin (must be non-zero), newOwner is the target owner
    function testFuzz_property(address adminCaller, address newOwner) public {
        // keep addresses in wide admissible domain
        vm.assume(adminCaller != address(0));
        vm.assume(newOwner != address(0));

        // We need the caller of setOwner to be the admin (the deployer was msg.sender in setUp -> c's admin is address(this) at construction time)
        // But contract C set admin = payable(msg.sender) at deployment; in setUp we deployed from this test contract, so the test contract (address(this)) is admin.
        // To exercise tx.origin vs param difference, we will deploy a thin forwarder contract whose runtime caller is the forwarder contract.

        // Deploy a forwarder from the fuzzer-chosen adminCaller: this makes tx.origin == adminExtern (EOA) while msg.sender inside C will be the forwarder.
        // We want the forwarder to act as admin (msg.sender inside setOwner), so we must make the forwarder be the admin recorded in C. But C's admin is set at construction to msg.sender (the test contract), so to make the call originate from an address that is equal to admin, we instead make the test contract delegate a call through a proxy pattern: we will have the test contract perform vm.prank(adminCaller) to create a ContractProxy which will BE the admin when calling setOwner. However, simpler: redeploy a fresh C instance from adminCaller so that that admin is adminCaller.

        // Deploy a fresh C with admin = adminCaller by using vm.prank to make deployment originate from adminCaller
        vm.startPrank(adminCaller);
        C c2 = new C();
        vm.stopPrank();

        // Now c2.admin == adminCaller (private) and owner initially == adminCaller (constructor set owner = msg.sender)
        // We want the call to setOwner to be made by the admin (adminCaller). To trigger the mutant difference, the adminCaller must be a contract so that tx.origin differs from the contract's intended _owner param in some cases.
        // The fuzzer provides adminCaller as an address (EOA with no code). We must create a contract that will act as the caller (so msg.sender is the contract) while tx.origin remains adminCaller. Deploy CallerHelper from adminCaller so that CallerHelper is a contract whose tx.origin==adminCaller when it makes the call into c2.

        // Deploy helper as if created by adminCaller
        vm.startPrank(adminCaller);
        CallerHelper helper = new CallerHelper();
        // Now have the helper call c2.setOwner(newOwner). This call will have msg.sender == address(helper) and tx.origin == adminCaller.
        helper.callSetOwner(address(c2), newOwner);
        vm.stopPrank();

        // The universal property: after the admin (here: helper acting on behalf of adminCaller) calls setOwner(newOwner), the contract's owner() must equal the provided newOwner.
        // Observe c2.owner() through its public getter. If the mutant set owner = tx.origin, owner() would equal adminCaller (tx.origin) instead of newOwner when adminCaller != newOwner.

        assertTrue(c2.owner() == newOwner);
    }
}

// Helper contract deployed by adminCaller; when it calls c.setOwner, tx.origin == adminCaller and msg.sender == address(this)
contract CallerHelper {
    function callSetOwner(address target, address newOwner) external {
        C(target).setOwner(newOwner);
    }
}

