        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        // The admin is the deployer (address(this) in setUp created c), which is address(this) in setUp
        // We need two scenarios: when the caller is the admin and when it's a non-admin.
        // The universal property: only admin can change owner in the reference implementation.
        // We'll execute setOwner as the fuzzed caller and then assert that if the caller is NOT the admin,
        // the owner's value cannot become the caller (i.e., only admin calls succeed in reference);
        // but because we must have exactly one assertTrue and it must hold for reference for ALL inputs
        // and be violated by the mutant for SOME input, we craft the assertion as follows:

        // Determine admin address: it was the deployer in setUp(), which is this test contract's address.
        address admin = address(this);

        // First, ensure caller has ETH so vm.prank can send transactions (not strictly required here but safe)
        vm.deal(caller, 1 ether);

        bool ok;
        // attempt the call as the fuzzed caller; capture success/failure
        vm.prank(caller);
        try c.setOwner(newOwner) returns (bool res) {
            ok = res;
        } catch {
            ok = false;
        }

        // Single assertion: In the correct contract, only the admin can successfully change owner.
        // Therefore, after any call to setOwner by `caller`, if caller != admin then the contract's owner
        // must NOT equal newOwner (i.e., the attempted change must have failed to set owner to newOwner).
        // This is a universal property over all inputs; the mutant that inverts the check will allow
        // non-admin callers to set owner, violating this assertion for some inputs (when caller != admin).
        if (caller != admin) {
            // For non-admin callers, reference ensures owner() != newOwner for all inputs
            assertTrue(c.owner() != newOwner);
        } else {
            // For admin caller, the admin may change owner; then owner should equal newOwner
            assertTrue(c.owner() == newOwner);
        }
    }
}

