contract InvMutTest is Test {
    C c;
    address deployer;

    function setUp() public {
        // test runner is the deployer/admin
        deployer = address(this);
        c = new C();
    }

    // fuzzed params: attacker candidate (an address) and a newOwner to set
    function testFuzz_property(address caller, address newOwner) public {
        // Keep domain wide but avoid trivial zero-address newOwner which is still admissible;
        // bound not strictly necessary, but ensure caller is not the deployer (admin) to expose difference
        // We allow caller==deployer too — the property must hold for all callers, but the bug should
        // allow a specific non-admin (the current owner) to succeed. To ensure we can make caller the
        // current owner, we'll first set owner to caller via a call from admin (deployer).

        // 1) admin (deployer) sets owner to `caller`.
        bool ok;
        // call setOwner as admin (this contract is deployer/admin)
        try c.setOwner(caller) {
            ok = true;
        } catch {
            ok = false;
        }
        // On the reference contract this must succeed (deployer is admin). If it somehow fails,
        // abort this fuzz case (rare). Keep admissible domain wide by assuming success.
        vm.assume(ok);

        // 2) Now act as `caller` and attempt to call setOwner again to set to newOwner.
        // In the correct contract only admin (deployer) may call setOwner; since caller is not
        // necessarily the deployer, this call must fail unless caller==deployer. We want a universal
        // property that for ANY caller address the following holds: only admin can set owner.
        // We'll observe whether the call succeeds.
        bool secondCallSucceeded;
        vm.prank(caller);
        try c.setOwner(newOwner) {
            secondCallSucceeded = true;
        } catch {
            secondCallSucceeded = false;
        }

        // Single assertion: the reference contract ensures that a caller who is not the original admin
        // cannot succeed in calling setOwner. That means: if `caller` != deployer then secondCallSucceeded == false.
        // We express it as: either caller is the deployer (then success may be true) OR the second call must have failed.
        // This is a general rule the reference satisfies for ALL inputs; the mutant (which uses owner instead of admin)
        // will allow caller (who we made the owner in step 1) to succeed when caller != deployer, causing this assertion to fail.
        assertTrue(caller == deployer || !secondCallSucceeded);
    }
}
